import type { QuranIndex, SurahData } from './types';
import { SURAH_MAP } from './surah-map';

// Bundled Quran data (Tanzil Hafs text, generated by scripts/build-quran-data.mjs).
// Static per-surah imports (src/data/surah-map.ts) so Metro/web can code-split
// cleanly — dynamic require patterns are rejected in SDK 58.

const index = require('../../assets/data/quran/index.json') as QuranIndex;

export function getIndex(): QuranIndex {
  return index;
}

export function getSurah(number: number): SurahData {
  return SURAH_MAP[number];
}

/** 1-based global ayah position across the Quran (1..6236). */
export function globalAyahNumber(surah: number, ayah: number): number {
  let offset = 0;
  for (let i = 1; i < surah; i++) {
    offset += index.surahs[i - 1].ayahCount;
  }
  return offset + ayah;
}

/** Juz number → first global ayah position. */
export function juzStartGlobal(juz: number): number {
  let pos = 1;
  for (const s of index.surahs) {
    if (s.number === 1 && juz === 1) return 1;
    const data = getSurah(s.number);
    const first = data.ayahs.find((a) => a.juz === juz);
    if (first) return globalAyahNumber(s.number, first.number);
  }
  return pos;
}
